CREATE TABLE users (id uuid PRIMARY KEY, username varchar(32) NOT NULL UNIQUE CHECK (username ~ '^[a-z0-9_]{4,32}$'), password_hash varchar(255) NOT NULL, active boolean NOT NULL DEFAULT true, role varchar(5) NOT NULL DEFAULT 'USER' CHECK(role IN ('USER','ADMIN')));
CREATE TABLE spring_session (primary_id char(36) PRIMARY KEY, session_id char(36) NOT NULL UNIQUE, creation_time bigint NOT NULL, last_access_time bigint NOT NULL, max_inactive_interval integer NOT NULL, expiry_time bigint NOT NULL, principal_name varchar(100));
CREATE INDEX spring_session_expiry_idx ON spring_session(expiry_time);
CREATE INDEX spring_session_principal_idx ON spring_session(principal_name);
CREATE TABLE spring_session_attributes (session_primary_id char(36) NOT NULL REFERENCES spring_session(primary_id) ON DELETE CASCADE, attribute_name varchar(200) NOT NULL, attribute_bytes bytea NOT NULL, PRIMARY KEY(session_primary_id,attribute_name));
CREATE TABLE auth_rate_limits (bucket varchar(120) PRIMARY KEY, window_start timestamptz NOT NULL, used integer NOT NULL CHECK(used>=0), expires_at timestamptz NOT NULL);
CREATE INDEX auth_rate_expiry ON auth_rate_limits(expires_at);
CREATE TABLE api_quotas (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, bucket varchar(80) NOT NULL, used integer NOT NULL CHECK(used>=0), expires_at timestamptz NOT NULL, PRIMARY KEY(user_id,bucket));
CREATE TABLE api_request_leases (id uuid PRIMARY KEY, user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE INDEX api_leases_user ON api_request_leases(user_id,expires_at);
CREATE TABLE sites (id uuid PRIMARY KEY, name varchar(160) NOT NULL, homepage_url varchar(2048) NOT NULL, normalized_homepage_url varchar(2048) NOT NULL UNIQUE, description varchar(1000) NOT NULL DEFAULT '', admin_note varchar(2000) NOT NULL DEFAULT '', status varchar(10) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','ACTIVE','PAUSED','ARCHIVED')), version bigint NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), archived_at timestamptz);
CREATE TABLE sources (id uuid PRIMARY KEY, site_id uuid NOT NULL REFERENCES sites(id), label varchar(160) NOT NULL, type varchar(10) NOT NULL CHECK(type IN ('RSS','ATOM','JSON_API')), endpoint_url varchar(2048) NOT NULL, normalized_endpoint_url varchar(2048) NOT NULL, language varchar(20) NOT NULL DEFAULT 'en', enabled boolean NOT NULL DEFAULT false, interval_seconds integer NOT NULL DEFAULT 900 CHECK(interval_seconds>=300), rights_status varchar(12) NOT NULL DEFAULT 'UNREVIEWED' CHECK(rights_status IN ('UNREVIEWED','APPROVED','RESTRICTED','DISABLED')), allow_metadata boolean NOT NULL DEFAULT false, allow_display boolean NOT NULL DEFAULT false, allow_summary boolean NOT NULL DEFAULT false, allow_body boolean NOT NULL DEFAULT false, allow_store boolean NOT NULL DEFAULT false, allow_translation boolean NOT NULL DEFAULT false, allow_image boolean NOT NULL DEFAULT false, allow_external_ai boolean NOT NULL DEFAULT false, terms_url varchar(2048), terms_checked_on date, review_note varchar(2000) NOT NULL DEFAULT '', json_mapping jsonb NOT NULL DEFAULT '{}', secret_ref varchar(100), validation_status varchar(12) NOT NULL DEFAULT 'NOT_TESTED' CHECK(validation_status IN ('NOT_TESTED','PASSED','FAILED')), validated_at timestamptz, next_run_at timestamptz NOT NULL DEFAULT now(), retry_after timestamptz, version bigint NOT NULL DEFAULT 0, archived_at timestamptz, etag varchar(500), last_modified varchar(100), UNIQUE(site_id, normalized_endpoint_url));
CREATE INDEX sources_due ON sources(next_run_at) WHERE enabled AND archived_at IS NULL;
CREATE TABLE fetch_runs (id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources(id), started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, result varchar(20) NOT NULL, new_count integer NOT NULL DEFAULT 0, updated_count integer NOT NULL DEFAULT 0, error_code varchar(80));
CREATE TABLE articles (id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources(id), source_guid varchar(2048) NOT NULL, canonical_url varchar(2048) NOT NULL, title varchar(500) NOT NULL, summary_bullets jsonb NOT NULL DEFAULT '[]', summary_mode varchar(30) NOT NULL, language varchar(20) NOT NULL, input_hash char(64) NOT NULL, processing_version varchar(30) NOT NULL DEFAULT 'extractive-v1', public boolean NOT NULL DEFAULT true, summary_locked boolean NOT NULL DEFAULT false, tags_locked boolean NOT NULL DEFAULT false, published_at timestamptz, collected_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(source_id,source_guid), UNIQUE(source_id,canonical_url));
CREATE INDEX articles_public_time ON articles(collected_at DESC,id) WHERE public;
CREATE TABLE article_revisions (id uuid PRIMARY KEY, article_id uuid NOT NULL REFERENCES articles(id), input_hash char(64) NOT NULL, changed_at timestamptz NOT NULL DEFAULT now(), change_kind varchar(30) NOT NULL);
CREATE TABLE tags (id uuid PRIMARY KEY, slug varchar(60) NOT NULL UNIQUE, name varchar(100) NOT NULL, category varchar(60) NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE tag_aliases (alias varchar(100) PRIMARY KEY, tag_id uuid NOT NULL REFERENCES tags(id));
CREATE TABLE tag_redirects (old_id uuid PRIMARY KEY REFERENCES tags(id), canonical_id uuid NOT NULL REFERENCES tags(id), CHECK(old_id<>canonical_id));
CREATE TABLE article_tags (article_id uuid NOT NULL REFERENCES articles(id), tag_id uuid NOT NULL REFERENCES tags(id), confidence numeric(4,3) NOT NULL CHECK(confidence BETWEEN 0 AND 1), method varchar(20) NOT NULL, locked boolean NOT NULL DEFAULT false, PRIMARY KEY(article_id,tag_id));
CREATE TABLE news_editions (id uuid PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL);
CREATE TABLE news_edition_items (edition_id uuid NOT NULL REFERENCES news_editions(id) ON DELETE CASCADE, position integer NOT NULL CHECK(position>=0), article_id uuid NOT NULL REFERENCES articles(id), PRIMARY KEY(edition_id,position), UNIQUE(edition_id,article_id));
CREATE TABLE content_jobs (id uuid PRIMARY KEY, source_id uuid NOT NULL REFERENCES sources(id), status varchar(12) NOT NULL CHECK(status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCELLED')), site_version bigint NOT NULL, source_version bigint NOT NULL, attempts integer NOT NULL DEFAULT 0, available_at timestamptz NOT NULL DEFAULT now(), lease_until timestamptz, lease_token uuid, created_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz, error_code varchar(80));
CREATE UNIQUE INDEX one_live_job_per_source ON content_jobs(source_id) WHERE status IN ('QUEUED','RUNNING');
CREATE INDEX job_claim ON content_jobs(status,available_at,lease_until);
CREATE TABLE worker_status (id varchar(100) PRIMARY KEY, heartbeat_at timestamptz NOT NULL);
CREATE TABLE admin_actions (id uuid PRIMARY KEY, admin_id uuid, action varchar(50) NOT NULL, target_id uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
